#!/usr/bin/env python3
"""Writes docs/deliverables/07-test-results.md from review/test-results/results.json (the last FULL run of test/run-all.mjs),
review/qa/safety-results.md and review/qa/parity-results.csv. Re-run after every full run:  python3 scripts/gen-test-results.py"""
import csv, json, re, pathlib
root = pathlib.Path(__file__).resolve().parent.parent
r = json.loads((root / 'review/test-results/results.json').read_text())
s = r['summary']; suites = r['suites']
safety = (root / 'review/qa/safety-results.md').read_text()
m = re.search(r'(\d+) case ids\. PASS (\d+) · FAIL (\d+) · NOT-RUNNABLE (\d+)', safety)
parity = list(csv.DictReader(open(root / 'review/qa/parity-results.csv', encoding='utf8')))
pc = {}
for row in parity: pc[row['status']] = pc.get(row['status'], 0) + 1
secs = lambda ms: f"{ms/1000:.1f}"
out = []
a = out.append
a('# 07 · Test results\n')
a(f"Deliverable 7 (prompt Part 21, item 7) · generated by `scripts/gen-test-results.py` from `review/test-results/results.json` · Psyflo × Harvest unified demo\n")
a(f"Last full run **{r['runId']}** · commit `{r['commit']}` · node {r['env']['node']} · Playwright Chromium · demo time {r['env']['time']} · preset {r['env']['preset']} · {r['env']['workers']} workers · base port {r['env']['basePort']}.\n")
a(f"**{s['pass']} of {s['pass']+s['fail']+s.get('flaky',0)+s.get('skip',0)} suites pass** · {s['fail']} fail · {s.get('flaky',0)} flaky · tests {s['tests']['pass']} pass / {s['tests']['fail']} fail / {s['tests']['skip']} skipped · {s['durationMs']/60000:.1f} min wall clock.\n")
a("A skipped test is a case that cannot run in this environment; each says why in its log (`review/test-results/<suite>.log`). Nothing was loosened to pass: where a feature was removed, its tests were removed with it and the parity map says so.\n")
a('## 1. Results per suite\n')
a('| Suite | Status | Pass | Fail | Skip | Seconds |\n|---|---|---|---|---|---|')
for x in sorted(suites, key=lambda x: x['name']):
    c = x['counts']; a(f"| {x['name']} | {x['status']} | {c['pass']} | {c['fail']} | {c['skip']} | {secs(x['durationMs'])} |")
a('')
a('## 2. Safety cases\n')
if m: a(f"`review/qa/safety-results.md`: **{m.group(1)} case ids** from `review/05b-safety-test-plan.md`: PASS {m.group(2)}, FAIL {m.group(3)}, NOT-RUNNABLE {m.group(4)}. NOT-RUNNABLE cases name the reason (a Track Time case was removed by the Nov 11 feedback; the others need a real device or a real payer).\n")
a('## 3. Parity (nothing silently dropped)\n')
a('`review/qa/parity-results.csv` has one row per feature of the master demo and the v3 reference: ' + ', '.join(f"{k} {v}" for k, v in sorted(pc.items())) + f" (total {len(parity)}). `docs/deliverables/02-feature-preservation-matrix.md` is generated from it. Rows for Track Time are DROPPED-WITH-REASON (feedback Nov 11); the My Work rows are MOVED to Dashboard and Documentation.\n")
a('## 4. What this round changed in the tests (Nov 11 feedback)\n')
a('- **Added:** `dashboard` (patient roster, scope per role, filters, expand and collapse, confirmation strip, 390 px), `patient` (chart, authorization section, out-of-scope id), `documentation` (scope per role, filters, review drawer, approve and return end to end, administrator sees no note text, direct support denied), and tests in `authorizations` for the unit bar, the deadline icon and the filters.')
a('- **Removed:** `time` and `time-panel` (Track Time). Safety case IIU-10 is reported NOT-RUNNABLE: removed by feedback.')
a('- **Rewritten to follow the new screens:** routes (redirect table, home targets), presenter, a11y, audit, visual, ui-kit, roles, settings, family, errors, s1, s2, s5, s6, safety (EXA-02, EXA-03, EXA-05 now read the Dashboard), parity, hosted (the clinician lands on the Dashboard).')
a('- **Defects the new tests found and that were fixed:** a guardian or school actor received the whole roster from `clientsInScope` (now returns nothing for portal roles); touch targets under 24 px on the Dashboard header at 400 px; a stale test that measured layout after the previous test had scrolled the page.\n')
a('## 5. What was not tested\n')
a('| Item | Why | Owner |\n|---|---|---|')
for x in r.get('manual', []): a(f"| {x['id']} | not run here; status {x['status']} | {x['owner']} |")
a('| Dashboard, Documentation, patient chart and Authorizations with the direct support and site supervisor staff | built from their feedback and checked on screenshots at 1440 and 390 px; not yet put in front of them | Product |')
a('| The hosted link on the real artifact host | the sandboxed iframe is simulated by a sandboxed iframe in Chromium; data resets on reload; PDFs open as text | QA |')
a('| Scribe microphone | the scripted call (about 48 s) and typed input are tested; a live microphone is not | QA |')
a('')
a('Re-run: `node test/run-all.mjs --ports 5100 --workers 4` (about 15 minutes), then `node test/lib/safety-report.mjs`, `python3 scripts/gen-deliverables.py` and `python3 scripts/gen-test-results.py`.\n')
(root / 'docs/deliverables/07-test-results.md').write_text('\n'.join(out))
print('wrote 07-test-results.md', s)
